import{_ as e,o as l,c as a,a0 as d}from"./chunks/framework.DQOulFGV.js";const x=JSON.parse('{"title":"第5章 大 Key 与热 Key","description":"","frontmatter":{},"headers":[],"relativePath":"redis/03-cache-engineering/chapter-05-big-hot-key.md","filePath":"redis/03-cache-engineering/chapter-05-big-hot-key.md"}'),i={name:"redis/03-cache-engineering/chapter-05-big-hot-key.md"};function s(r,t,n,h,y,o){return l(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="第5章-大-key-与热-key" tabindex="-1">第5章 大 Key 与热 Key <a class="header-anchor" href="#第5章-大-key-与热-key" aria-label="Permalink to &quot;第5章 大 Key 与热 Key&quot;">​</a></h1><blockquote><p>大 Key 与热 Key 是两类容易引发线上故障的 key：大 Key 拖慢命令执行、占用带宽；热 Key 让单点承受全部流量。本章讲解二者的定义、危害、发现与处理。</p></blockquote><hr><h2 id="_5-1-大-key" tabindex="-1">5.1 大 Key <a class="header-anchor" href="#_5-1-大-key" aria-label="Permalink to &quot;5.1 大 Key&quot;">​</a></h2><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>大 Key 指单个 key 的 value 过大。不同场景的判定阈值不同：</p><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">判定标准（参考）</th></tr></thead><tbody><tr><td style="text-align:left;">String</td><td style="text-align:left;">value 超过 10KB</td></tr><tr><td style="text-align:left;">Hash/List/Set/ZSet</td><td style="text-align:left;">元素数量超过几万，或整体超过几 MB</td></tr></tbody></table><h3 id="危害" tabindex="-1">危害 <a class="header-anchor" href="#危害" aria-label="Permalink to &quot;危害&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">危害</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">阻塞命令</td><td style="text-align:left;">大 Key 的读写耗时长，单线程下阻塞其他请求</td></tr><tr><td style="text-align:left;">占用带宽</td><td style="text-align:left;">大 Key 读写占用大量网络带宽</td></tr><tr><td style="text-align:left;">拖慢迁移</td><td style="text-align:left;">集群迁移时大 Key 迁移慢，影响扩容</td></tr><tr><td style="text-align:left;">内存碎片</td><td style="text-align:left;">大对象反复增删产生碎片</td></tr></tbody></table><h3 id="发现" tabindex="-1">发现 <a class="header-anchor" href="#发现" aria-label="Permalink to &quot;发现&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bigkeys</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 扫描最大的 key（内存分析）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --memusage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 查看单个 key 的内存占用</span></span></code></pre></div><p><code>--bigkeys</code> 基于 SCAN 遍历，不会阻塞主线程，适合生产环境排查。</p><h3 id="处理" tabindex="-1">处理 <a class="header-anchor" href="#处理" aria-label="Permalink to &quot;处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">拆分 Hash</td><td style="text-align:left;">大 Hash 按业务维度拆成多个小 Hash</td></tr><tr><td style="text-align:left;">分片存储</td><td style="text-align:left;">大 key 拆成多个子 key 分散存储</td></tr><tr><td style="text-align:left;">异步删除</td><td style="text-align:left;">用 <code>UNLINK</code> 代替 <code>DEL</code>，避免删除阻塞</td></tr><tr><td style="text-align:left;">选择合适结构</td><td style="text-align:left;">大数据量选 List/Set 而非 String 存整块</td></tr></tbody></table><blockquote><p>删除大 Key 要用 <code>UNLINK</code>（异步删除）而非 <code>DEL</code>（同步删除），<code>DEL</code> 大 Key 会阻塞主线程。</p></blockquote><hr><h2 id="_5-2-热-key" tabindex="-1">5.2 热 Key <a class="header-anchor" href="#_5-2-热-key" aria-label="Permalink to &quot;5.2 热 Key&quot;">​</a></h2><h3 id="定义-1" tabindex="-1">定义 <a class="header-anchor" href="#定义-1" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>热 Key 指访问频率极高、被大量请求集中访问的 key，例如秒杀商品、热搜词。</p><h3 id="危害-1" tabindex="-1">危害 <a class="header-anchor" href="#危害-1" aria-label="Permalink to &quot;危害&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">危害</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">单点压力</td><td style="text-align:left;">流量集中在单个 key 所在的节点，成为瓶颈</td></tr><tr><td style="text-align:left;">集群倾斜</td><td style="text-align:left;">Cluster 模式下热 key 所在分片负载过高</td></tr><tr><td style="text-align:left;">击穿风险</td><td style="text-align:left;">热 key 过期瞬间引发缓存击穿（见第 2 章）</td></tr></tbody></table><h3 id="发现-1" tabindex="-1">发现 <a class="header-anchor" href="#发现-1" aria-label="Permalink to &quot;发现&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>MONITOR</code> 命令</td><td style="text-align:left;">实时观察命令流，找出高频 key（有性能开销）</td></tr><tr><td style="text-align:left;">客户端埋点</td><td style="text-align:left;">在业务代码里统计 key 访问频次</td></tr><tr><td style="text-align:left;">代理层统计</td><td style="text-align:left;">通过 Redis 代理（如 Codis）统计热点</td></tr></tbody></table><h3 id="处理-1" tabindex="-1">处理 <a class="header-anchor" href="#处理-1" aria-label="Permalink to &quot;处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">本地缓存</td><td style="text-align:left;">热点数据缓存在应用进程内，减少 Redis 访问</td></tr><tr><td style="text-align:left;">Key 复制分散</td><td style="text-align:left;">热 key 复制多份（key1、key2...），分散到不同分片</td></tr><tr><td style="text-align:left;">读写分离</td><td style="text-align:left;">读请求分流到从节点</td></tr><tr><td style="text-align:left;">缓存预热</td><td style="text-align:left;">提前加载热点数据，避免冷启动击穿</td></tr></tbody></table><hr><h2 id="_5-3-小结对比" tabindex="-1">5.3 小结对比 <a class="header-anchor" href="#_5-3-小结对比" aria-label="Permalink to &quot;5.3 小结对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">大 Key</th><th style="text-align:left;">热 Key</th></tr></thead><tbody><tr><td style="text-align:left;">核心问题</td><td style="text-align:left;">体积过大</td><td style="text-align:left;">访问过热</td></tr><tr><td style="text-align:left;">主要危害</td><td style="text-align:left;">阻塞、带宽、迁移慢</td><td style="text-align:left;">单点压力、集群倾斜</td></tr><tr><td style="text-align:left;">发现工具</td><td style="text-align:left;"><code>--bigkeys</code>、<code>--memusage</code></td><td style="text-align:left;">MONITOR、客户端埋点</td></tr><tr><td style="text-align:left;">处理思路</td><td style="text-align:left;">拆分、异步删除</td><td style="text-align:left;">本地缓存、分散、预热</td></tr></tbody></table><p>判别口诀：<strong>大 Key 拆、热 Key 散</strong>——大 Key 要拆小，热 Key 要分散。</p>`,29)])])}const f=e(i,[["render",s]]);export{x as __pageData,f as default};
